function mPhoto(value){return typeof value==='string' && value.length<3000000 && /^data:image\/(jpeg|png);base64,[A-Za-z0-9+\/=]+$/.test(value)}
const products=[{id:1,name:'Kavis Ahşap Abajur',cat:'Aydınlatma',material:'Doğal ahşap · Sıcak bir dokunuş',price:890,tag:'Atölye seçkisi',kind:'lamp',bg:'#e7e3d8'},{id:2,name:'Botanik Duvar Panosu',cat:'Dekorasyon',material:'Lazer kesim · Doğadan ilhamla',price:650,tag:'Doğadan ilhamla',kind:'leaf',bg:'#e8e9de'},{id:3,name:'Kişiye Özel İsimlik',cat:'Kişiye özel',material:'Sana özel · İsim ve tarih',price:390,tag:'Kişiselleştirilebilir',kind:'name',bg:'#ece2d5'},{id:4,name:'Çizgi Ahşap Saat',cat:'Dekorasyon',material:'Minimal tasarım · Doğal doku',price:720,tag:'Zamansız',kind:'clock',bg:'#e5e3dc'},{id:5,name:'Fotoğraflı Anı Kutusu',cat:'Kişiye özel',material:'Fotoğraf baskısı · Sana özel',price:480,tag:'Fotoğrafını ekle',photoRequired:true,kind:'box',bg:'#e8e3d8'},{id:6,name:'Çiçek Ahşap Altlık Seti',cat:'Hediyelik',material:'4 parçalı set · Sofrana doğallık',price:280,tag:'Küçük mutluluklar',kind:'coaster',bg:'#e8e8de'}];
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(n);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function art(p){let shape='';if(p.kind==='lamp'){shape='<ellipse cx="200" cy="310" rx="75" ry="12" fill="#74603c" opacity=".13"/><path d="M194 265v38h13v-38" fill="#9d744b"/><ellipse cx="200" cy="305" rx="45" ry="8" fill="url(#wood)"/><path d="M127 238Q143 133 200 117Q257 133 273 238Z" fill="#bd8a4b"/><path d="M137 236Q153 134 200 120Q248 134 263 236" fill="#f2ce7e"/>'+Array.from({length:17},(_,i)=>{let x=135+i*8;return `<path d="M${x} 239Q${160+i*4.8} 145 200 120" fill="none" stroke="#936438" stroke-width="3.5"/>`}).join('')+'<ellipse cx="200" cy="239" rx="73" ry="9" fill="#8e623b"/><ellipse cx="200" cy="238" rx="62" ry="5" fill="#eecb8c"/>'}if(p.kind==='leaf'){shape='<rect x="106" y="73" width="188" height="244" rx="95" fill="url(#wood)" filter="url(#shadow)"/><rect x="120" y="87" width="160" height="216" rx="80" fill="#e2e3d6"/><path d="M198 289V126" stroke="#9e743f" stroke-width="6"/>'+[0,1,2,3].map(i=>`<path d="M198 ${270-i*36}Q${139-i*2} ${264-i*35} 143 ${223-i*34}Q187 ${222-i*34} 198 ${270-i*36}ZM201 ${252-i*35}Q256 ${251-i*35} 255 ${209-i*34}Q208 ${213-i*34} 201 ${252-i*35}Z" fill="url(#wood)"/>`).join('')}if(p.kind==='name'){shape='<g transform="rotate(-7 200 200)"><path d="M91 292V162a109 109 0 0 1 218 0v130Z" fill="url(#wood)" filter="url(#shadow)"/><path d="M104 280V164a96 96 0 0 1 192 0v116Z" fill="none" stroke="#8b663c" stroke-width="1"/><text x="200" y="200" text-anchor="middle" font-family="Georgia,serif" font-style="italic" font-size="45" fill="#6e4a2d">Laleli</text><path d="M160 220q40 15 80 0" fill="none" stroke="#86613c"/><text x="200" y="249" text-anchor="middle" font-family="sans-serif" font-size="8" letter-spacing="3" fill="#775534">SENİN HİKÂYEN</text></g>'}if(p.kind==='clock'){shape='<circle cx="200" cy="197" r="113" fill="url(#wood)" filter="url(#shadow)"/>'+Array.from({length:12},(_,i)=>`<path d="M200 96v${i%3===0?15:9}" transform="rotate(${i*30} 200 197)" stroke="#735637" stroke-width="2"/>`).join('')+'<path d="M200 130v67l48 28" fill="none" stroke="#3e4539" stroke-width="5" stroke-linecap="round"/><circle cx="200" cy="197" r="6" fill="#3e4539"/>'}if(p.kind==='box'){shape='<g filter="url(#shadow)"><path d="m93 164 179-25 41 61-175 29Z" fill="#d4b186"/><path d="m138 229 175-29v81l-175 30Z" fill="url(#wood)"/><path d="m93 164 45 65v82l-45-67Z" fill="#ab8051"/><path d="m92 158 179-25 44 63-179 30Z" fill="url(#wood)" stroke="#926b40"/><path d="m136 226 179-30" stroke="#88603a" stroke-width="3"/><text x="203" y="183" transform="rotate(-8 203 183)" text-anchor="middle" font-family="Georgia" font-style="italic" font-size="20" fill="#795332">güzel anılar</text><rect x="217" y="230" width="16" height="12" rx="2" fill="#8a744c"/></g>'}if(p.kind==='coaster'){shape=[{x:148,y:152},{x:252,y:159},{x:148,y:254},{x:253,y:263}].map(({x,y},idx)=>`<g transform="translate(${x} ${y}) rotate(${idx*17})" filter="url(#shadow)"><path d="M0-47C12-62 28-48 26-32C49-40 61-17 43-4C63 12 46 36 28 27C28 53 1 60-7 37C-24 58-48 43-36 22C-64 24-65-5-41-12C-58-32-32-51-19-35C-21-53-6-59 0-47Z" fill="url(#wood)"/><circle r="26" fill="none" stroke="#9a7246"/><path d="M-17 0h34M0-17v34" stroke="#ae8455" stroke-width="1"/></g>`).join('')}
return `<svg viewBox="0 0 400 390" role="img" aria-label="${p.name} temsili ürün çizimi"><defs><linearGradient id="wood" x1="0" y1="0" x2="1" y2=".3"><stop stop-color="#d6b58b"/><stop offset=".35" stop-color="#bd945e"/><stop offset=".62" stop-color="#d7b58a"/><stop offset="1" stop-color="#bd925f"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="190%" height="190%"><feDropShadow dx="6" dy="14" stdDeviation="11" flood-color="#51452c" flood-opacity=".2"/></filter></defs><rect width="400" height="390" fill="${p.bg}"/><ellipse cx="200" cy="365" rx="190" ry="110" fill="#fff" opacity=".08"/>${shape}</svg>`}
let cart=[];try{cart=JSON.parse(localStorage.getItem('laleli-cart')||'[]').filter(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<1000).map(i=>({id:i.id,qty:i.qty,note:String(i.note||''),photo:typeof i.photo==='string' && i.photo.length<3000000 && mPhoto(i.photo)?i.photo:'',photoName:String(i.photoName||'')}))}catch{}let category='Tümü',query='';const $=s=>document.querySelector(s);function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function render(){let list=products.filter(p=>(category==='Tümü'||p.cat===category)&&p.name.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));if($('#sort').value==='asc')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='desc')list.sort((a,b)=>b.price-a.price);$('#products').innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-art"><button data-open="${p.id}" aria-label="${p.name} detayları">${art(p)}</button><span class="tag">${p.tag}</span><button class="quick-add" data-add="${p.id}" aria-label="${p.name} sepete ekle">+</button></div><div class="product-meta"><div><button class="product-name" data-open="${p.id}">${p.name}</button><small>${p.material}</small></div><span class="price">${money(p.price)}</span></div></article>`).join(''):'<p class="empty">Aramana uygun bir parça bulunamadı. Başka bir kelime deneyebilirsin.</p>'}
function save(){try{localStorage.setItem('laleli-cart',JSON.stringify(cart))}catch{}$('#count').textContent=cart.reduce((s,i)=>s+i.qty,0)}function add(id,note=''){const row=cart.find(i=>i.id===id&&i.note===note);if(row)row.qty++;else cart.push({id,qty:1,note});save();toast('Güzel bir seçim. Sepetine eklendi.')}function openProduct(id){const p=products.find(p=>p.id===id);$('#product-detail').innerHTML=`<div class="detail-grid"><div>${art(p)}</div><div><div class="eyebrow">${p.cat.toLocaleUpperCase('tr')}</div><h2>${p.name}</h2><p>${p.material}</p><strong>${money(p.price)}</strong><p>Ahşabın doğal dokusunu yaşam alanına taşıyan örnek koleksiyon parçası.</p>${p.cat==='Kişiye özel'?'<label>Yazılacak isim / not<input id="personal-note" maxlength="100" placeholder="Örn. Deniz & Ece"></label>':''}<button class="button dark" id="detail-add">Sepetime ekle <span>+</span></button><p class="demo-note">Temsili tasarım ve fiyat. Henüz satışa açık değildir.</p></div></div>`;$('#detail-add').onclick=()=>{add(id,$('#personal-note')?.value.trim()||'');$('#product-dialog').close()};$('#product-dialog').showModal()}
function renderCart(){const count=cart.reduce((s,i)=>s+i.qty,0);$('#cart-total-count').textContent=`(${count})`;$('#cart-items').innerHTML=cart.length?cart.map((i,index)=>{const p=products.find(p=>p.id===i.id);return `<div class="cart-row">${art(p)}<div><p>${p.name}</p>${i.note?`<small>${safe(i.note)}</small>`:''}<p>${money(p.price)}</p><div class="quantity"><button data-qty="${index}" data-delta="-1" aria-label="Adedi azalt">−</button><span>${i.qty}</span><button data-qty="${index}" data-delta="1" aria-label="Adedi artır">+</button></div></div><button class="remove" data-remove="${index}" aria-label="Ürünü kaldır">×</button></div>`}).join(''):'<div class="empty">Sepetinde henüz bir parça yok.<br><button class="button dark" id="browse">Koleksiyonu keşfet ↗</button></div>';$('#cart-bottom').innerHTML=cart.length?`<div class="cart-summary"><span>Ara toplam</span><strong>${money(cart.reduce((s,i)=>s+products.find(p=>p.id===i.id).price*i.qty,0))}</strong></div><button class="button dark" id="download-cart">Seçimlerimi indir ↗</button><p>Mağazamız hazırlık aşamasında. Ürünler ve fiyatlar temsilidir; henüz ödeme veya sipariş alınmıyor.</p>`:'';$('#browse')?.addEventListener('click',()=>{$('#cart-dialog').close();location.hash='koleksiyon'});$('#download-cart')?.addEventListener('click',()=>download('laleli-secimlerim.txt','LALELİ TASARIM — ÖRNEK ÜRÜN SEÇİMLERİ\n\n'+cart.map(i=>{const p=products.find(p=>p.id===i.id);return `${p.name} · ${i.qty} adet · ${money(p.price*i.qty)}${i.note?'\nKişiselleştirme: '+i.note:''}`}).join('\n\n')+'\n\nBu belge bir sipariş değildir. Temsili ürünler ve fiyatlar içerir.'))}
function download(name,content){const u=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Dosyan hazır, indirme başlatıldı.')}document.addEventListener('click',e=>{const open=e.target.closest('[data-open]'),addBtn=e.target.closest('[data-add]'),qty=e.target.closest('[data-qty]'),remove=e.target.closest('[data-remove]');if(open)openProduct(+open.dataset.open);if(addBtn){const p=products.find(p=>p.id===+addBtn.dataset.add);p.cat==='Kişiye özel'?openProduct(p.id):add(p.id)}if(qty){let i=+qty.dataset.qty;cart[i].qty+=+qty.dataset.delta;if(cart[i].qty<1)cart.splice(i,1);save();renderCart()}if(remove){cart.splice(+remove.dataset.remove,1);save();renderCart()}});document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#sort').onchange=render;$('#search-btn').onclick=()=>{$('#search-wrap').hidden=false;$('#koleksiyon').scrollIntoView({behavior:'smooth'});$('#search').focus({preventScroll:true})};$('#search').oninput=e=>{query=e.target.value;render()};$('#cart-btn').onclick=()=>{renderCart();$('#cart-dialog').showModal()};$('#custom-btn').onclick=()=>$('#custom-dialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#custom-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);download('laleli-tasarim-fikrim.txt',`LALELİ TASARIM — TASARIM BRİEFİ\n\nAd: ${f.get('name')}\nÜrün: ${f.get('type')}\nFikir: ${f.get('idea')}\n\nBu dosya cihazına indirildi. Atölyeye gönderilmedi.`);$('#custom-dialog').close()};$('#year').textContent=new Date().getFullYear();save();render();
